//
// Compares every linear stage netlist with the ngspice AC response of the full reference subcircuit
// (tests/reference/*.csv, generated by tools/make_references.sh), then checks the discretised (DK) response
// against the analogue response at the oversampled rate.
//
// Usage: BlueChannelStageTest <reference dir>

#include "Circuit/DkStage.h"
#include "Circuit/Netlists.h"
#include "Model/Calibration.h"

#include <cmath>
#include <complex>
#include <cstdio>
#include <fstream>
#include <functional>
#include <map>
#include <sstream>
#include <string>
#include <vector>

using namespace bluechannel::circuit;
namespace calibration = bluechannel::model::calibration;
using cd = std::complex<double>;

struct Row { double f, db, ph; };

static std::vector<Row> readCsv(const std::string& path)
{
    std::vector<Row> rows;
    std::ifstream in(path);
    std::string line;
    std::getline(in, line);
    while (std::getline(in, line))
    {
        Row r{};
        if (std::sscanf(line.c_str(), "%lf,%lf,%lf", &r.f, &r.db, &r.ph) == 3) rows.push_back(r);
    }
    return rows;
}

struct Case
{
    const char* file;
    const char* netlist;
    std::vector<std::pair<const char*, double>> params;
    const char* out = nullptr;      // output name; nullptr = first output
    const char* minus = nullptr;    // differential output
    double tolDb = 0.25;
    double phaseMaxHz = 20000.0;    // phase compared up to this frequency
    double polesHz = 0.0;           // model-side closed-loop amplifier pole applied to the netlist response
};

static double wrap(double deg)
{
    while (deg > 180.0) deg -= 360.0;
    while (deg < -180.0) deg += 360.0;
    return deg;
}

// Discrete-time response of the compiled state-space model at frequency f.
static cd discreteResponse(DkStage& s, int out, int in, double f, double fs)
{
    // Probe by running a complex exponential through the real-valued model is not possible, so evaluate
    // the response from impulse data: simulate an impulse and take a DFT at f (long enough to decay).
    const int n = 1 << 16;
    s.reset();
    std::vector<double> u(size_t(s.numInputs()), 0.0), y(size_t(std::max(1, s.numOutputs())), 0.0);
    cd acc = 0.0;
    const double w = 2.0 * M_PI * f / fs;
    for (int i = 0; i < n; ++i)
    {
        u[size_t(in)] = i == 0 ? 1.0 : 0.0;
        s.process(u.data(), y.data());
        acc += y[size_t(out)] * std::polar(1.0, -w * i);
    }
    return acc;
}

int main(int argc, char** argv)
{
    const std::string dir = argc > 1 ? argv[1] : "tests/reference";
    using namespace netlists;
    std::vector<Case> cases = {
        { "line_input", kLineInput, {} },
        { "trim_0", kTrim, { { "trim", 0.0 }, { "phase", 0 } } },
        { "trim_50", kTrim, { { "trim", 0.5 }, { "phase", 0 } } },
        { "trim_100", kTrim, { { "trim", 1.0 }, { "phase", 1 } } },
        { "filters_wide", kFilters, { { "lpr", 0.001 }, { "hpr", 47000 } } },
        { "filters_mid", kFilters, { { "lpr", 10000 }, { "hpr", 1000 } } },
        { "filters_narrow", kFilters, { { "lpr", 47000 }, { "hpr", 0.001 } } },
        { "shelves_a", kShelves, { { "lfgain", 0 }, { "hfgain", 1 }, { "lfsel", 0 }, { "hfsel", 0 } } },
        { "shelves_b", kShelves, { { "lfgain", 1 }, { "hfgain", 0 }, { "lfsel", 3 }, { "hfsel", 3 } } },
        { "shelves_c", kShelves, { { "lfgain", 0.25 }, { "hfgain", 0.75 }, { "lfsel", 5 }, { "hfsel", 5 } } },
        { "shelves_d", kShelves, { { "lfgain", 0.5 }, { "hfgain", 0.5 }, { "lfsel", 2 }, { "hfsel", 4 } } },
        { "lmf_a", kLmf, { { "gain", 0 }, { "q", 0.5 }, { "freq", 0.5 }, { "x3", 0 } } },
        { "lmf_b", kLmf, { { "gain", 1 }, { "q", 1 }, { "freq", 0 }, { "x3", 1 } } },
        { "lmf_c", kLmf, { { "gain", 0.2 }, { "q", 0 }, { "freq", 1 }, { "x3", 0 } } },
        { "lmf_d", kLmf, { { "gain", 0.5 }, { "q", 0.5 }, { "freq", 0.5 }, { "x3", 0 } } },
        { "hmf_a", kHmf, { { "gain", 0 }, { "q", 0.5 }, { "freq", 0.5 }, { "x3", 0 } } },
        { "hmf_b", kHmf, { { "gain", 1 }, { "q", 1 }, { "freq", 0 }, { "x3", 1 } } },
        { "hmf_c", kHmf, { { "gain", 0.2 }, { "q", 0 }, { "freq", 1 }, { "x3", 1 } } },
        // The reference uses a 20k frequency pot; the netlist uses 47k (see Netlists.h), so scale the fraction.
        { "deess_a", kDeesser, { { "freq", 0.5 * 20.0 / 47.0 } } },
        { "deess_b", kDeesser, { { "freq", 0.05 * 20.0 / 47.0 } } },
        { "deess_c", kDeesser, { { "freq", 1.0 * 20.0 / 47.0 } } },
        { "limiter_low", kLimiterSplit, {}, "low" },
        { "limiter_mid", kLimiterSplit, {}, "mid", nullptr, 0.5 },   // small difference band: op-amp gain error
        { "limiter_high", kLimiterSplit, {}, "high" },
        { "fader_100", kFader, { { "fader", 1.0 } } },
        { "fader_71", kFader, { { "fader", 0.71 } } },
        { "fader_20", kFader, { { "fader", 0.2 } } },
        { "output", kOutput, {}, "hot", "cold" },
    };
    for (int k = 0; k <= 6; ++k)
    {
        static std::vector<std::string> names(7);
        names[size_t(k)] = "line_gain_" + std::to_string(k);
        cases.push_back({ names[size_t(k)].c_str(), kLineGain, { { "gain", double(k) } } });
    }
    for (int k = 0; k <= 11; ++k)
    {
        static std::vector<std::string> names(12);
        names[size_t(k)] = "mic_gain_" + std::to_string(k);
        cases.push_back({ names[size_t(k)].c_str(), kMicInput,
                          { { "gain", double(k) }, { "rsrc", 0.0 }, { "zscale", 1.0 }, { "air", 0.0 } },
                          // Tolerance: the reference op-amp macro adds about 8 degrees more lag at 17.8 kHz at the
                          // highest gains (about 1.2 us); magnitude stays within 0.35 dB (docs/MEASUREMENTS.md).
                          nullptr, nullptr, 0.35, 10000.0,
                          // The model adds the amplifier's closed-loop pole (gain-bandwidth / noise gain), as MicStage.
                          10e6 / std::max(1.0, std::pow(10.0, (calibration::kMicGainDb[std::min(k, 6)] - 14.0) / 20.0)) });
    }

    int failures = 0;
    std::printf("%-16s %6s %6s %9s %9s %8s %8s\n", "case", "states", "N", "dB@1k", "maxdB", "maxdeg", "dkdB");
    for (auto& c : cases)
    {
        const auto ref = readCsv(dir + "/" + c.file + ".csv");
        if (ref.empty()) { std::printf("%-16s missing reference\n", c.file); ++failures; continue; }
        DkStage s(c.netlist);
        for (auto& [name, v] : c.params)
        {
            const int p = s.param(name);
            if (p < 0) { std::printf("%s: no param %s\n", c.file, name); return 2; }
            s.setParam(p, v);
        }
        const int out = c.out ? s.output(c.out) : 0;
        const int minus = c.minus ? s.output(c.minus) : -1;
        auto analog = [&](double f) {
            cd h = s.analogResponse(out, 0, f);
            if (minus >= 0) h -= s.analogResponse(minus, 0, f);
            if (c.polesHz > 0.0) h /= cd(1.0, f / c.polesHz);
            return h;
        };
        double maxDb = 0, maxDeg = 0, db1k = 0, fAt = 0;
        for (auto& r : ref)
        {
            if (r.f < 20.0 || r.f > 20000.0) continue;
            const cd h = analog(r.f);
            const double db = 20.0 * std::log10(std::abs(h) + 1e-30);
            // Phase only where the response is not deep in a null.
            const double dDb = db - r.db;
            if (std::abs(r.f - 1000.0) / 1000.0 < 0.1) db1k = db;
            if (r.db > -40.0)
            {
                if (std::abs(dDb) > maxDb) { maxDb = std::abs(dDb); fAt = r.f; }
                if (r.f <= c.phaseMaxHz) maxDeg = std::max(maxDeg, std::abs(wrap(std::arg(h) * 180.0 / M_PI - r.ph)));
            }
        }
        // Discretisation check at 96 kHz (2x at 48 kHz) against the analogue response, 20 Hz..16 kHz.
        s.setSampleRate(96000.0);
        s.update();
        double dkDb = 0;
        for (double f : { 31.5, 100.0, 1000.0, 4000.0, 10000.0 })
        {
            cd hd = discreteResponse(s, out, 0, f, 96000.0);
            if (minus >= 0) hd -= discreteResponse(s, minus, 0, f, 96000.0);
            const cd ha = analog(f);
            if (std::abs(ha) < 0.1) continue;   // skip stop bands (-20 dB), where warping is irrelevant
            dkDb = std::max(dkDb, std::abs(20.0 * std::log10(std::abs(hd) / std::abs(ha))));
        }
        const bool ok = maxDb <= c.tolDb && maxDeg <= 5.0 && dkDb <= 0.5;
        failures += !ok;
        std::printf("%-16s %6d %6d %9.3f %9.3f %8.2f %8.3f  @%.0f Hz %s\n", c.file, s.numStates(), s.numUnknowns(), db1k,
                    maxDb, maxDeg, dkDb, fAt, ok ? "" : "FAIL");
    }
    std::printf("%s (%d failures)\n", failures ? "FAILED" : "PASSED", failures);
    return failures ? 1 : 0;
}
